cards_upsert as (
  insert into public.cards (
    card_set_id, collector_number, card_name, card_type,
    guide_category_label, guide_category_code, rarity_label,
    mechanic_label, illustration_style, guide_order, source_url, image_source_url
  )
  select
    s.id, c.collector_number, c.card_name, c.card_type,
    c.guide_category_label, c.guide_category_code, c.rarity_label,
    c.mechanic_label, c.illustration_style, c.guide_order, c.source_url, c.image_source_url
  from set_row s cross join card_input c
  on conflict (card_set_id, collector_number) do update
    set card_name = excluded.card_name,
        card_type = excluded.card_type,
        guide_category_label = excluded.guide_category_label,
        guide_category_code = excluded.guide_category_code,
        rarity_label = excluded.rarity_label,
        mechanic_label = excluded.mechanic_label,
        illustration_style = excluded.illustration_style,
        guide_order = excluded.guide_order,
        source_url = excluded.source_url,
        image_source_url = excluded.image_source_url
  returning id, collector_number
),
