    collector_number text,
    variant_key text,
    variant_label text,
    finish_code text,
    guide_marker text,
    checklist_group text,
    is_master_set_target boolean
  )
),
variants_upsert as (
  insert into public.card_print_variants (
    card_id, variant_key, variant_label, finish_code,
    guide_marker, checklist_group, is_master_set_target
  )
  select
    c.id, v.variant_key, v.variant_label, v.finish_code,
    v.guide_marker, v.checklist_group, v.is_master_set_target
  from variant_input v
  join cards_upsert c using (collector_number)
  on conflict (card_id, variant_key) do update
    set variant_label = excluded.variant_label,
        finish_code = excluded.finish_code,
        guide_marker = excluded.guide_marker,
        checklist_group = excluded.checklist_group,
        is_master_set_target = excluded.is_master_set_target
  returning id
)
select count(*) as imported_variant_rows from variants_upsert;